const d = new Date(Date.now() - 24 * 60 * 60 * 1000);
const pad = n => String(n).padStart(2, '0');
const ymd = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
return [{
  json: {
    since: `${ymd} 00:00:00`,
    until: `${ymd} 23:59:59`,
    dateLabel: ymd
  }
}];

const raw = $input.first().json.data || [];

const keep = /error|fail(?:ed|ure)?|warn|critical|denied|timeout|panic|oom|degraded|corrupt|unreachable|refused|expired|exceeded|bounced|blocked|deferred|rejected|unauthenticated|reset by peer|retry|retries|nic link is (down|up)|no.?carrier|netdev watchdog|bonding:.*(down|fail)|link is down|stp topology change|rx_error|tx_error|soft lockup|hung_task|rcu_sched|machine check|\bmce\b|thermal|throttl|killed process|out of memory/i;

// Bridge-port state changes on a REAL physical/bond NIC are worth flagging (uplink flapping).
// Changes on virtual VM interfaces (tap/veth/fwln/fwpr/fwbr) are normal VM start/stop noise, so they're excluded.
const physicalIfaceBridgeChange = /vmbr\d+: port \d+\((?!tap|veth|fwln|fwpr|fwbr)[a-z0-9.]+\) entered (disabled|blocking) state/i;

let lines = raw
  .map(l => l.t)
  .filter(t => keep.test(t) || physicalIfaceBridgeChange.test(t));

const counts = new Map();
for (const line of lines) {
  const key = line.replace(/^\S+\s+\d+\s+[\d:]+\s+\S+\s+/, '').trim();
  counts.set(key, (counts.get(key) || 0) + 1);
}

const deduped = [...counts.entries()].map(([msg, n]) => n > 1 ? `[x${n}] ${msg}` : msg);

return [{
  json: {
    text: deduped.join('\n'),
    originalLineCount: raw.length,
    filteredLineCount: lines.length,
    dedupedLineCount: deduped.length,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

const data = $input.first().json;
const lines = data.text.split('\n').filter(Boolean);
const CHUNK_SIZE = 1200;
const chunks = [];
for (let i = 0; i < lines.length; i += CHUNK_SIZE) {
  chunks.push(lines.slice(i, i + CHUNK_SIZE).join('\n'));
}
if (chunks.length === 0) chunks.push('(no notable lines after filtering)');

return chunks.map((text, idx) => ({
  json: {
    text,
    chunkIndex: idx + 1,
    totalChunks: chunks.length,
    dateLabel: data.dateLabel
  }
}));

const content = $input.item.json.text ?? '';
const chunkInfo = $('Chunk Log For Analysis').item.json;
return [{
  json: {
    chunkIndex: chunkInfo.chunkIndex,
    extracted: content
  }
}];

const items = $input.first().json.data || [];
const list = items.map(i => i.extracted).filter(Boolean);
const meaningful = list.filter(x => x.trim().toUpperCase() !== 'NONE');
const combined = meaningful.length ? meaningful.join('\n') : 'NONE';

return [{
  json: {
    combinedIssues: combined,
    totalChunks: list.length,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

const raw = $input.first().json.stdout ?? $input.first().json.data ?? '';

function section(name, text) {
  const re = new RegExp(`===${name}===\\n([\\s\\S]*?)(?=\\n===|$)`);
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

function summarizeTemps(tempRaw) {
  if (!tempRaw) return '(sensors not available)';
  const readingRe = /([A-Za-z0-9 _+\-]+?):\s*\+?(-?\d+\.\d+)\s*°?C\s*\(high\s*=\s*\+?(-?\d+\.\d+)\s*°?C(?:,\s*crit\s*=\s*\+?(-?\d+\.\d+)\s*°?C)?\)/gi;
  const readings = [];
  let m;
  while ((m = readingRe.exec(tempRaw)) !== null) {
    readings.push({
      label: m[1].trim(),
      temp: parseFloat(m[2]),
      high: parseFloat(m[3]),
      crit: m[4] ? parseFloat(m[4]) : null
    });
  }
  if (readings.length === 0) return tempRaw.slice(0, 300);

  const temps = readings.map(r => r.temp);
  const max = Math.max(...temps);
  const min = Math.min(...temps);
  const avg = (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1);
  const nearThreshold = readings.filter(r => r.temp >= r.high - 5);

  let summary = `${readings.length} sensors reporting. Min ${min}C, max ${max}C, avg ${avg}C (thresholds around high=${readings[0].high}C, crit=${readings[0].crit ?? 'n/a'}C).`;
  summary += nearThreshold.length
    ? ' Near/at threshold: ' + nearThreshold.map(r => `${r.label} ${r.temp}C`).join(', ') + '.'
    : ' All sensors comfortably below threshold.';
  return summary;
}

const loadavgRaw = section('LOADAVG', raw);
const cpuCountRaw = section('CPUCOUNT', raw);
const uptimeRaw = section('UPTIME', raw);
const tempRaw = section('TEMP', raw);
const nicRaw = section('NIC_STATS', raw);

const loadParts = loadavgRaw.split(/\s+/);
const load1 = parseFloat(loadParts[0]) || 0;
const load5 = parseFloat(loadParts[1]) || 0;
const load15 = parseFloat(loadParts[2]) || 0;
const cpuCount = parseInt(cpuCountRaw, 10) || 1;
const loadPerCore = Number((load5 / cpuCount).toFixed(2));

// Split ip -s link output into one block per interface
const ifaceBlocks = nicRaw.split(/\n(?=\d+: )/);
const nicSummaries = [];

for (const block of ifaceBlocks) {
  const headerMatch = block.match(/^\d+:\s+([^\s@:]+)[@:].*?<([^>]*)>/);
  if (!headerMatch) continue;
  const name = headerMatch[1];
  const flags = headerMatch[2];

  // Skip loopback and virtual VM/bridge interfaces - focus on physical NICs and bonds
  if (/^(lo|tap|veth|fwln|fwpr|fwbr|vmbr)/i.test(name)) continue;

  const state = flags.includes('LOWER_UP') ? 'UP' : (flags.includes('UP') ? 'UP (no carrier)' : 'DOWN');

  // First 4 numbers after RX:/TX: are always bytes, packets, errors, dropped regardless of ip version
  const rxMatch = block.match(/RX:[^\n]*\n\s*(\d+)\s+(\d+)\s+(\d+)\s+(\d+)/i);
  const txMatch = block.match(/TX:[^\n]*\n\s*(\d+)\s+(\d+)\s+(\d+)\s+(\d+)/i);

  const rxErrors = rxMatch ? parseInt(rxMatch[3], 10) : 0;
  const rxDropped = rxMatch ? parseInt(rxMatch[4], 10) : 0;
  const txErrors = txMatch ? parseInt(txMatch[3], 10) : 0;
  const txDropped = txMatch ? parseInt(txMatch[4], 10) : 0;

  nicSummaries.push(
    `${name}: ${state}, RX errors=${rxErrors} dropped=${rxDropped}, TX errors=${txErrors} dropped=${txDropped}`
  );
}

const hardwareSummary =
`Load average (1/5/15m): ${load1}/${load5}/${load15} across ${cpuCount} CPU threads (5m load per core: ${loadPerCore})
Uptime: ${uptimeRaw || 'unknown'}

Temperatures:
${summarizeTemps(tempRaw)}

Physical network interfaces:
${nicSummaries.length ? nicSummaries.join('\n') : '(no physical interfaces found)'}`;

return [{
  json: {
    hardwareSummary,
    load1, load5, load15, cpuCount, loadPerCore,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

