const raw = ($input.item.json.text ?? '').trim();
const status = /^STATUS:\s*ISSUES/i.test(raw) ? 'ISSUES' : 'OK';

const hardwareSummary = $('Parse Hardware Stats').first().json.hardwareSummary ?? '';

function escapeHtml(s) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Plain text version: AI report + raw hardware snapshot underneath
const report = hardwareSummary
  ? `${raw}\n\n---\nHardware snapshot (raw):\n${hardwareSummary}`
  : raw;

// HTML version: same content, with <br> for line breaks since HTML ignores '\n'
const reportHtml = `<div style="font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.5;">
${escapeHtml(raw).replace(/\n/g, '<br>\n')}
${hardwareSummary
  ? `<br><br><hr style="border: none; border-top: 1px solid #ccc;"><br><strong>Hardware snapshot (raw):</strong><br>${escapeHtml(hardwareSummary).replace(/\n/g, '<br>\n')}`
  : ''}
</div>`;

return [{
  json: {
    report,
    reportHtml,
    status,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

